// Define the pin for the built-in LED
const int ledPin = LED_BUILTIN; 

void setup() {
  Serial.begin(115200);         // Initialize serial communication
  pinMode(ledPin, OUTPUT);    // Set the LED pin as an output
}

void loop() {
  // Check if data is available to read
  if (Serial.available() > 0) {
    // Read the incoming string until a newline character
    String command = Serial.readStringUntil('\n');

    // Clean up the string by removing extra spaces or newline characters
    command.trim(); 

    // Check the command and toggle the LED
    if (command == "on"||command == "ON"||command == "On") {
      digitalWrite(ledPin, HIGH);
      Serial.println("LED turned ON");
    } 
    else if (command == "off"||command == "OFF"||command == "Off") {
      digitalWrite(ledPin, LOW);
      Serial.println("LED turned OFF");
    }
  }
}
